import json
from collections import defaultdict

with open('input.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

markers = [r for r in data if r['id'].startswith('marker_')]
marker_sum = sum(r['value'] for r in markers)

group_values = defaultdict(list)
for r in data:
    group_values[r['group']].append(r['value'])
group_max = {g: max(values) for g, values in group_values.items()}

output = {'marker_sum': marker_sum, 'group_max': group_max, 'markers': markers}
with open('output.json', 'w', encoding='utf-8') as f:
    json.dump(output, f, indent=2, ensure_ascii=False)

lines = ['Benchmark Summary', '=================', '', 'Sum of marker values: ' + str(marker_sum), '', 'Per-group maximum values:']
for g in sorted(group_max.keys()):
    lines.append('  ' + g + ': ' + str(group_max[g]))
lines.append('')
lines.append('Marker records:')
for m in markers:
    lines.append('  ' + m['id'] + ': ' + m['note'] + ' (value=' + str(m['value']) + ', group=' + m['group'] + ')')

with open('summary.txt', 'w', encoding='utf-8') as f:
    for line in lines:
        f.write(line + chr(10))

print('Done!')
